import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link } from "react-router-dom";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import {
  fetchEmployees,
  deleteEmployee,
} from "../redux/employee/employeesSlice";

const EmployeeList = () => {
  const dispatch = useDispatch();
  const { employees, loading, error } = useSelector((state) => state.employee);

  // 🚀 Fetch data when component mounts
  useEffect(() => {
    dispatch(fetchEmployees());
  }, [dispatch]);

  // 🗑️ Delete button handler
  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
      dispatch(deleteEmployee(id));
    }
  };

  // 🔧 Action column template
  const actionBodyTemplate = (rowData) => {
    return (
      <div className="d-flex gap-2">
        <Link to={`/edit/${rowData.id}`} className="btn btn-sm btn-warning">
          Edit
        </Link>
        <button
          onClick={() => handleDelete(rowData.id)}
          className="btn btn-sm btn-danger"
        >
          Delete
        </button>
      </div>
    );
  };

  // 📦 Loading and error states
  const status = loading ? "loading" : error ? "failed" : "succeeded";

  return (
    <div className="card p-3 mt-4">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h3 className="m-0">Employee List</h3>
        <Link to="/add" className="btn btn-primary">
          Add Employee
        </Link>
      </div>

      {status === "loading" && <div>Loading...</div>}
      {status === "failed" && (
        <div className="text-danger">Error: {JSON.stringify(error)}</div>
      )}

      <DataTable
        value={employees}
        paginator
        rows={5}
        stripedRows
        rowsPerPageOptions={[5, 10, 20]}
        tableStyle={{ minWidth: "50rem" }}
        emptyMessage="No employees found."
      >
        <Column field="name" header="Name" sortable />
        <Column field="lastname" header="Last Name" sortable />
        <Column field="email" header="Email" sortable />
        <Column field="position" header="Position" sortable />
        <Column body={actionBodyTemplate} header="Actions" />
      </DataTable>
    </div>
  );
};

export default EmployeeList;
